// @ts-check
import js from '@eslint/js';
import { defineConfig } from 'eslint/config';
import tseslint from 'typescript-eslint';
import { createNodeResolver, importX } from 'eslint-plugin-import-x';
import security from 'eslint-plugin-security';
import eslintConfigPrettier from 'eslint-config-prettier/flat';

export default defineConfig(
  {
    ignores: [
      'node_modules/**',
      // Generated by scripts/build-client.ts from src/web/client.
      'src/web/public/js/**',
      // Generated by scripts/static/build.ts.
      'dist/**',
      '.ignore/**',
      // Claude Code worktrees: other branches' checkouts, already git-ignored.
      '.claude/**',
    ],
  },

  // `projectService` resolves the nearest tsconfig.json per file — the root one
  // for backend code, src/web/client/tsconfig.json for frontend.
  {
    files: ['**/*.{js,ts}'],
    extends: [
      js.configs.recommended,
      tseslint.configs.strictTypeChecked,
      tseslint.configs.stylisticTypeChecked,
    ],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      // Express dispatches on arity, so handlers keep parameters they never
      // read — prefix with `_` to opt out. `args: 'all'` is what makes the
      // opt-out explicit; the default ignores parameters before the last used
      // one, hiding an unused `req` that precedes a used `next`.
      '@typescript-eslint/no-unused-vars': [
        'error',
        {
          args: 'all',
          argsIgnorePattern: '^_',
          caughtErrorsIgnorePattern: '^_',
        },
      ],
    },
  },

  // Every runtime import specifier must name a file that exists on disk —
  // the one failure mode neither tsc nor the bundler catches, since tsc maps
  // "./foo.js" onto foo.ts while Node resolves literally and throws
  // ERR_MODULE_NOT_FOUND at boot.
  //
  // The Node resolver is deliberate: eslint-import-resolver-typescript would
  // reproduce tsc's blind spot rather than check against it.
  {
    files: ['**/*.{js,ts}'],
    plugins: { 'import-x': importX },
    settings: {
      'import-x/resolver-next': [
        createNodeResolver({ extensions: ['.js', '.mjs', '.ts', '.json'] }),
      ],
    },
    rules: {
      'import-x/no-unresolved': 'error',
    },
  },

  // Three rules from eslint-plugin-security, not its `recommended` preset: the
  // preset's remaining rules either target patterns absent from an ESM/Express 5
  // codebase (csurf ordering, `require`, legacy Buffer, Handlebars) or are
  // syntactic heuristics with no dataflow behind them —
  // detect-object-injection alone flags ~655 ordinary bracket accesses here.
  //
  // These three are at zero hits today and exist to keep it that way.
  {
    files: ['**/*.{js,ts}'],
    plugins: { security },
    rules: {
      // Trojan Source (CVE-2021-42574): bidirectional overrides make source
      // read differently from what runs. Review cannot catch it, and the
      // Portuguese copy here means non-ASCII text is unremarkable.
      'security/detect-bidi-characters': 'error',
      'security/detect-child-process': 'error',
      // Ticket and nickname patterns are matched against public request input.
      'security/detect-unsafe-regex': 'error',
    },
  },

  // `return next()` and `return res.redirect(…)` are Express's own idiom for
  // "stop here", and both return void, so no-confusing-void-expression rejects
  // them. The rule's ignoreVoidReturningFunctions option does not help:
  // @types/express types RequestHandler's return as `unknown`, not `void`.
  //
  // Off only where request handlers live; still enforced elsewhere.
  {
    files: [
      'src/middleware/**/*.ts',
      'src/api/**/*.ts',
      'src/**/*.{controller,routes}.ts',
      'src/web/routes/**/*.ts',
    ],
    rules: {
      '@typescript-eslint/no-confusing-void-expression': 'off',
    },
  },

  // `k6/*` modules are built into the k6 binary, so no file on disk can back
  // them; @types/k6 covers the types. Every other specifier is still checked.
  {
    files: ['loadtest/**/*.ts'],
    rules: {
      'import-x/no-unresolved': ['error', { ignore: ['^k6(/|$)'] }],
    },
  },

  // node:test's `describe` and `it` return promises the runner itself tracks;
  // awaiting or voiding every call would be noise.
  {
    files: ['**/*.test.ts'],
    rules: {
      '@typescript-eslint/no-floating-promises': 'off',
    },
  },

  // Client tests are excluded from src/web/client/tsconfig.json, the nearest
  // tsconfig.json, so the project service would find no project for them. Named
  // explicitly instead.
  {
    files: ['src/web/client/**/*.test.ts'],
    languageOptions: {
      parserOptions: {
        projectService: false,
        project: './src/web/client/tsconfig.test.json',
        tsconfigRootDir: import.meta.dirname,
      },
    },
  },

  // User-facing text lives in src/i18n/messages. An accented literal in client
  // code is almost always copy that skipped the catalog, so it fails early,
  // before `i18n:audit`. pt-BR-specific and incomplete — "Buscar" has no
  // accent — which is why the audit, not this rule, is the real guard.
  //
  // Admin services throw English diagnostics and name the refusal in
  // `details.reason`, so an accented literal there is copy that belongs in
  // `admin-errors`.
  {
    files: ['src/web/client/**/*.ts', 'src/modules/admin/**/*.ts'],
    rules: {
      'no-restricted-syntax': [
        'error',
        {
          selector: 'Literal[value=/[áàâãéêíóôõúçÁÀÂÃÉÊÍÓÔÕÚÇ]/]',
          message:
            'Read user-facing text from a message catalog; see docs/development/copy-management.md.',
        },
        {
          selector: 'TemplateElement[value.raw=/[áàâãéêíóôõúçÁÀÂÃÉÊÍÓÔÕÚÇ]/]',
          message:
            'Read user-facing text from a message catalog; see docs/development/copy-management.md.',
        },
      ],
    },
  },

  // Must stay last: turns off any stylistic rules above that would fight Prettier.
  eslintConfigPrettier,
);
